  // Combined Search and Filter Logic
  const filteredResidents = useMemo(() => {
    return residents.filter(r => {
      const matchesSearch = 
        r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.house.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.email.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'ALL' || r.status === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [residents, searchTerm, statusFilter]);

  // Reset pagination on filter change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, statusFilter]);

  const handleAddResident = (e: React.FormEvent) => {
    e.preventDefault();
    const id = (residents.length + 1).toString();
    const residentToAdd: Resident = { ...newResident, id };
    setResidents([residentToAdd, ...residents]);
    setShowAddModal(false);
    setNewResident({ name: '', email: '', house: '', phone: '', status: 'ACTIVE' });
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Are you sure you want to remove this resident?')) {
      setResidents(residents.filter(r => r.id !== id));
    }
  };

  /**
   * SPECIFIC EXPORT: Only exports what is currently visible in the table
   */
  const exportToCSV = () => {
    if (filteredResidents.length === 0) {
      alert("No data to export with current filters.");
      return;
    }

    const headers = ['ID', 'Name', 'Email', 'House', 'Phone', 'Status'];

    // Use filteredResidents instead of the full residents array
    const dataRows = filteredResidents.map(r => [
      r.id, 
      `"${r.name}"`, // Quote strings to handle commas in names/addresses
      r.email, 
      `"${r.house}"`, 
      r.phone, 
      r.status
    ]);

    const csvContent = [headers, ...dataRows].map(e => e.join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);

