                <button type="submit"
                  className="flex-1 px-6 py-3 bg-[#0068B6] text-white font-bold rounded-xl hover:bg-[#003067] shadow-lg shadow-blue-200 transition-all flex items-center justify-center gap-2 active:scale-95">
                  <Check size={18} /> Confirm Add
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

