          <div className="w-12 h-12 bg-green-50 rounded-full flex items-center justify-center text-green-600 group-hover:bg-green-600 group-hover:text-white transition-all">
            <DollarSign size={24} />
          </div>
          <div>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest">Total Collected</p>
            <p className="text-2xl font-black text-gray-900">${stats.paid.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl border shadow-sm flex items-center gap-4 group hover:border-orange-200 transition-colors">
          <div className="w-12 h-12 bg-orange-50 rounded-full flex items-center justify-center text-orange-600 group-hover:bg-orange-600 group-hover:text-white transition-all">
            <Calendar size={24} />
          </div>
          <div>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest">Outstanding Due</p>
            <p className="text-2xl font-black text-gray-900">${stats.pending.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl border shadow-sm flex items-center gap-4 group hover:border-blue-200 transition-colors">
          <div className="w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center text-blue-600 group-hover:bg-[#0068B6] group-hover:text-white transition-all">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-xs font-black text-gray-400 uppercase tracking-widest">Collection Rate</p>
            <p className="text-2xl font-black text-gray-900">{stats.ratio}%</p>
          </div>
        </div>
      </div>

      {/* Transaction Management Section */}
      <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
        <div className="p-4 border-b bg-gray-50/50 flex flex-col md:flex-row gap-4 items-center justify-between">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search by ID, Resident, or Unit..." 
              className="w-full pl-10 pr-4 py-2.5 bg-white text-black font-semibold border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#0068B6] outline-none transition-all placeholder:text-gray-400"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-2">
            <button className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-[#0068B6] bg-blue-50 px-4 py-2 rounded-xl border border-blue-100 hover:bg-blue-100 transition-colors">
              <Filter size={14} /> Filter
            </button>
            <button className="flex items-center gap-2 text-xs font-black uppercase tracking-widest text-gray-500 bg-white px-4 py-2 rounded-xl border border-gray-100 hover:bg-gray-50 transition-colors">
              <Download size={14} /> Export
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-white text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">
              <tr>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4">Transaction Details</th>
                {!isResidentView && <th className="px-6 py-4">Resident Info</th>}
                <th className="px-6 py-4">Amount</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredTransactions.map((trx) => (
                <tr key={trx.id} className="hover:bg-blue-50/30 transition-all group">
                  <td className="px-6 py-5 align-top">
                    <button 
                      onClick={() => {
                        if (isResidentView) return;
                        const next: Record<string, Transaction['status']> = { 'PAID': 'PENDING', 'PENDING': 'OVERDUE', 'OVERDUE': 'PAID' };
                        updateStatus(trx.id, next[trx.status]);
                      }}
                      className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${
                        trx.status === 'PAID' ? 'bg-green-50 text-green-700 border-green-200' :
                        trx.status === 'PENDING' ? 'bg-orange-50 text-orange-700 border-orange-200' : 'bg-red-50 text-red-700 border-red-200'
                      } ${!isResidentView && 'hover:scale-105 active:scale-95 shadow-sm'}`}
                    >
                      {trx.status}
                    </button>
                  </td>
                  <td className="px-6 py-5 align-top">
                    <p className="text-xs font-black text-gray-400 uppercase mb-1">{trx.id}</p>
                    <p className="text-sm font-bold text-gray-900">{trx.description}</p>
                    <div className="flex items-center gap-2 mt-1.5 text-[10px] font-bold text-gray-500 uppercase">
                      <Calendar size={12} /> {trx.date} 
                      <span className="opacity-30">•</span> 
                      {trx.method}
                    </div>
                  </td>
                  {!isResidentView && (
                    <td className="px-6 py-5 align-top">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-gray-100 flex items-center justify-center text-gray-500 font-black">
                          {trx.residentName.charAt(0)}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-gray-900">{trx.residentName}</p>
                          <p className="text-xs text-gray-500 font-medium">{trx.unit}</p>
                          <span className={`text-[9px] font-black uppercase px-1.5 py-0.5 rounded ${trx.residentType === 'OWNER' ? 'bg-amber-100 text-amber-700' : 'bg-blue-50 text-blue-600'}`}>
                            {trx.residentType}
                          </span>
                        </div>
                      </div>
                    </td>
                  )}
                  <td className="px-6 py-5 align-top">
                    <p className="text-lg font-black text-[#003067] tracking-tight">${trx.amount.toFixed(2)}</p>
                  </td>
                  <td className="px-6 py-5 text-right align-top">
                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button className="p-2 text-gray-400 hover:text-[#0068B6] hover:bg-blue-50 rounded-lg transition-all">
                        <Edit3 size={18} />
                      </button>
                      {!isResidentView && (
                        <button 
                          onClick={() => deleteTransaction(trx.id)}
                          className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"
                        >
                          <Trash2 size={18} />
                        </button>
                      )}
                      <button className="p-2 text-gray-400 hover:text-gray-900 transition-all">
                        <ArrowUpRight size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredTransactions.length === 0 && (
                <tr>
                  <td colSpan={5} className="py-20 text-center">
                    <div className="flex flex-col items-center gap-4 text-gray-300">
                      <DollarSign size={48} className="opacity-20" />
                      <div>
                        <p className="text-lg font-black text-gray-400">No records found</p>
                        <p className="text-sm font-medium">Try adjusting your search or filters.</p>
                      </div>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Record Payment Modal */}
      {showRecordModal && (
        <div className="fixed inset-0 z-[130] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#003067]/60 backdrop-blur-md" onClick={() => setShowRecordModal(false)} />
          <div className="relative w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-6 bg-gray-50 border-b flex items-center justify-between">
              <div>
                <h3 className="text-xl font-black text-[#003067]">Record New Payment</h3>
                <p className="text-xs text-gray-500 font-medium">Manual ledger entry for resident dues.</p>
              </div>
              <button onClick={() => setShowRecordModal(false)} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
                <X size={20} className="text-gray-500" />
              </button>
            </div>

            <form className="p-6 space-y-4" onSubmit={(e) => { e.preventDefault(); setShowRecordModal(false); alert('Payment recorded successfully!'); }}>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Resident / Unit</label>
                <select className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6] transition-all">
                  <option>Select Resident...</option>
                  <option>Alice Thompson (Block A, #12)</option>
                  <option>Bob Smith (Block C, #05)</option>
                  <option>Diana Prince (Block A, #42)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Amount ($)</label>
                  <input type="number" placeholder="0.00" className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6]" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Date</label>
                  <input type="date" className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6]" defaultValue={new Date().toISOString().split('T')[0]} />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Payment Method</label>
                <div className="grid grid-cols-3 gap-2">
                  {['Cash', 'Transfer', 'Cheque'].map(m => (
                    <button key={m} type="button" className="py-2 text-[10px] font-black uppercase tracking-tight border rounded-lg hover:bg-[#0068B6] hover:text-white transition-all">{m}</button>
                  ))}
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Description</label>
                <textarea rows={2} className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6]" placeholder="e.g. Oct Maintenance Fee"></textarea>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setShowRecordModal(false)} className="flex-1 px-6 py-3 bg-gray-100 text-gray-600 font-bold rounded-xl hover:bg-gray-200 transition-all">Cancel</button>
                <button type="submit" className="flex-1 px-6 py-3 bg-[#0068B6] text-white font-bold rounded-xl hover:bg-[#003067] shadow-lg shadow-blue-200 transition-all">Submit Entry</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Payments;

export enum UserRole {
  ADMIN = 'ADMIN',
  RESIDENT = 'RESIDENT'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
  houseNumber?: string;
}

export type ServiceCategory = 
  | 'MAINTENANCE_PERMIT' 
  | 'CONSTRUCTION_PERMIT' 
  | 'VENUE_PERMIT' 
  | 'INTERNET_INSTALL' 
  | 'BORROWERS_SLIP' 
  | 'SATISFACTION_FEEDBACK';

export interface ServiceRequest {
  id: string;
  residentId: string;
  residentName: string;
  title: string;
  description: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
  createdAt: string;
  category: ServiceCategory;
  imageUrl?: string;
  details?: any; // To store specific form data
}

export interface Announcement {
  id: string;
  title: string;
  content: string;
  date: string;
  author: string;
  category: 'URGENT' | 'GENERAL' | 'EVENT';
}

export interface Payment {
  id: string;
  residentId: string;
  amount: number;
  date: string;
  status: 'PAID' | 'PENDING' | 'OVERDUE';
  description: string;
}

import React, { useState, useRef } from 'react';
import { User, ServiceCategory } from '../../types';
import { 
  Camera, Image as ImageIcon, Send, Loader2, Sparkles, X, 
  HardHat, Wifi, Tent, Hammer, PenTool, MessageSquare, 
  Check, Info, FileText
} from 'lucide-react';
import { analyzeImage } from '../../services/geminiService';

const SubmitRequest: React.FC<{ user: User }> = ({ user }) => {
  const [category, setCategory] = useState<ServiceCategory | ''>('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({});
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleAIScan = async () => {
    if (!imagePreview) return;
    setIsAnalyzing(true);
    try {
      const base64Data = imagePreview.split(',')[1];
      const result = await analyzeImage(base64Data, 'Identify which Bliss III permit this is (Construction, Maintenance, Venue, Internet, or Borrower). Extract all fields found in the image and return a JSON summary.');
      setDescription(result || '');
      // In a real implementation, we would parse JSON and setCategory + setFormData
    } catch (error) {
      console.error('AI Analysis failed', error);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert(`Your ${category?.replace('_', ' ')} request has been submitted to the Admin Office.`);
    resetForm();
  };

  const resetForm = () => {
    setCategory('');
    setTitle('');
    setDescription('');
    setImagePreview(null);
    setFormData({});
  };

  if (!category) {
    return (
      <div className="max-w-4xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4">
        <div className="text-center space-y-2 mb-8">
          <h2 className="text-3xl font-black text-[#003067]">Community Service Portal</h2>
          <p className="text-gray-500 font-medium">Select the specific permit or request form you need.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <ServiceTypeCard 
            title="Maintenance Permit" 
            icon={Hammer} 
            desc="Repairs, leaks, or electrical issues in your unit or common areas."
            onClick={() => setCategory('MAINTENANCE_PERMIT')}
          />
          <ServiceTypeCard 
            title="Construction Permit" 
            icon={HardHat} 
            desc="Renovations, painting, tiling, or structural works."
            onClick={() => setCategory('CONSTRUCTION_PERMIT')}
          />
          <ServiceTypeCard 
            title="Venue & Common Area" 
            icon={Tent} 
            desc="Book Multi-Purpose Halls, Parks, or Basketball Courts."
            onClick={() => setCategory('VENUE_PERMIT')}
          />
          <ServiceTypeCard 
            title="Internet / Utilities" 
            icon={Wifi} 
            desc="Installation of internet, cable, or phone services."
            onClick={() => setCategory('INTERNET_INSTALL')}
          />
          <ServiceTypeCard 
            title="Borrower's Slip" 
            icon={PenTool} 
            desc="Borrow tools, equipment, or assets from the admin office."
            onClick={() => setCategory('BORROWERS_SLIP')}
          />
          <ServiceTypeCard 
            title="Satisfaction Feedback" 
            icon={MessageSquare} 
            desc="Rate our services and provide suggestions for improvement."
            onClick={() => setCategory('SATISFACTION_FEEDBACK')}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto pb-12 animate-in zoom-in-95 duration-200">
      <div className="bg-white rounded-3xl shadow-xl border overflow-hidden">
        {/* Sub-header */}
        <div className="bg-[#003067] p-6 text-white flex items-center justify-between">
          <div className="flex items-center gap-3">
             <button onClick={resetForm} className="p-2 hover:bg-white/10 rounded-xl transition-colors">
               <X size={20} />
             </button>
             <div>
               <h2 className="font-black text-lg uppercase tracking-tight">{category.replace('_', ' ')}</h2>
               <p className="text-xs text-blue-200">Bliss III Official E-Permit System</p>
             </div>
          </div>
          <FileText className="opacity-20" size={32} />
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {/* AI Helper Bar */}
          <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl flex items-center justify-between gap-4">
             <div className="flex items-center gap-3">
               <div className="w-8 h-8 rounded-full bg-blue-100 text-[#0068B6] flex items-center justify-center">
                 <Sparkles size={16} />
               </div>
               <p className="text-[10px] font-bold text-blue-800 uppercase tracking-widest">Digitalize Physical Form</p>
             </div>
             <button 
               type="button"
               onClick={() => fileInputRef.current?.click()}
               className="text-[10px] font-black bg-[#0068B6] text-white px-3 py-1.5 rounded-lg shadow-sm"
             >
               UPLOAD PHOTO
             </button>
          </div>

          <div className="space-y-4">
            {/* Common Header Fields */}
            <div className="grid grid-cols-2 gap-4">
              <FormField label="Full Name" value={user.name} disabled />
              <FormField label="Unit / Building" value={user.houseNumber || ''} disabled />
            </div>

            {/* DYNAMIC FORM LOGIC BASED ON CATEGORY */}
            {category === 'CONSTRUCTION_PERMIT' && (
              <div className="space-y-4 pt-4 border-t">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Work Checklist</p>
                <div className="grid grid-cols-2 gap-2">
                  {['Interior Painting', 'Ceiling Install', 'Tiling', 'Carpentry', 'Plumbing', 'Electrical'].map(work => (
                    <label key={work} className="flex items-center gap-2 p-2 rounded-xl bg-gray-50 border text-xs font-bold text-gray-700 cursor-pointer hover:bg-white hover:border-[#0068B6] transition-all">
                      <input type="checkbox" className="w-4 h-4 rounded text-[#0068B6]" />
                      {work}
                    </label>
                  ))}
                </div>
                <FormField label="Contractor Name" placeholder="Agency or Individual name" />
              </div>
            )}

            {category === 'VENUE_PERMIT' && (
              <div className="space-y-4 pt-4 border-t">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Venue Requested</p>
                <select className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6]">
                  <option>Select Facility...</option>
                  <option>Multi-Purpose Hall 1</option>
                  <option>Multi-Purpose Hall 2</option>
                  <option>Basketball Half Court</option>
                  <option>Park / Nagsabado Hall</option>
                </select>
                <div className="grid grid-cols-2 gap-4">
                   <FormField label="Event Date" type="date" />
                   <FormField label="Start Time" type="time" />
                </div>
              </div>
            )}

            {category === 'BORROWERS_SLIP' && (
              <div className="space-y-4 pt-4 border-t">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Items Requested</p>
                <textarea 
                  rows={3} 
                  placeholder="List items, quantity, and purpose of use..."
                  className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6]"
                />
              </div>
            )}

            {category === 'SATISFACTION_FEEDBACK' && (
              <div className="space-y-4 pt-4 border-t">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Service Rating</p>
                <div className="flex justify-between gap-2">
                  {['😡', '😐', '🙂', '🤩'].map((emoji, i) => (
                    <button type="button" key={i} className="flex-1 py-4 bg-gray-50 rounded-2xl border hover:border-[#0068B6] transition-all text-2xl grayscale hover:grayscale-0">
                      {emoji}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Standard Description Area */}
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Additional Notes</label>
              <textarea 
                rows={3}
                className="w-full px-4 py-3 bg-gray-50 text-black font-semibold border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-[#0068B6] transition-all"
                placeholder="Provide any extra details here..."
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </div>

            {/* Image Upload Preview */}
            {imagePreview && (
              <div className="relative rounded-2xl overflow-hidden border">
                <img src={imagePreview} alt="Preview" className="w-full aspect-video object-cover" />
                <button 
                  type="button"
                  onClick={() => setImagePreview(null)}
                  className="absolute top-2 right-2 p-1 bg-white/80 rounded-full hover:bg-white shadow-sm"
                >
                  <X className="w-5 h-5 text-gray-600" />
                </button>
                <div className="absolute bottom-4 left-4 right-4">
                  <button
                    type="button"
                    onClick={handleAIScan}
                    disabled={isAnalyzing}
                    className="w-full bg-[#0068B6]/90 backdrop-blur text-white px-4 py-2 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-[#0068B6] transition-all shadow-lg"
                  >
                    {isAnalyzing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                    {isAnalyzing ? "Processing Document..." : "Auto-fill from photo"}
                  </button>
                </div>
              </div>
            )}
          </div>

          <div className="pt-6 border-t flex flex-col gap-4">
             <div className="flex gap-2 items-start bg-amber-50 p-4 rounded-xl border border-amber-100">
               <Info size={18} className="text-amber-600 mt-1 shrink-0" />
               <p className="text-[10px] text-amber-800 font-bold leading-relaxed">
                 By submitting, you agree to the Bliss III Admin terms & conditions. Permits are subject to inspection and approval within 1-2 working days.
               </p>
             </div>

             <button
              type="submit"
