  const mockRequests: Record<string, RequestRecord[]> = {
    '1': [
      { id: 'REQ-101', category: 'CONSTRUCTION_PERMIT', title: 'Bedroom Extension', date: '2023-11-05', status: 'PENDING' },
      { id: 'REQ-052', category: 'MAINTENANCE_PERMIT', title: 'Faucet Repair', date: '2023-08-12', status: 'COMPLETED' },
    ],
    'default': [{ id: 'REQ-DEF', category: 'MAINTENANCE_PERMIT', title: 'General Maintenance', date: '2023-12-01', status: 'IN_PROGRESS' }]
  };

  const mockViolations: Record<string, ViolationRecord[]> = {
    '1': [
      { id: 'VIO-901', type: 'Noise Complaint', date: '2023-11-20', status: 'PENDING', fine: 50.00, description: 'Loud music after 10:00 PM (Weekday)' },
    ],
