                  onClick={() => setActiveTab('REQUESTS')} 
                  icon={ClipboardList} 
                  label="Requests" 
                />
                <TabButton 
                  active={activeTab === 'VIOLATIONS'} 
                  onClick={() => setActiveTab('VIOLATIONS')} 
                  icon={AlertTriangle} 
                  label="Violations" 
                />
              </div>
            </div>

            {/* Scrollable Modal Content */}
            <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-[#f8fafc]">
              {activeTab === 'PROFILE' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <DetailItem label="Full Email Address" value={selectedResident.email} />
                    <DetailItem label="Contact Number" value={selectedResident.phone} />
                    <DetailItem label="Status" value={selectedResident.status} />
                    <DetailItem label="Join Date" value={selectedResident.joinDate} />
                  </div>

                  {/* Summary Dashboard for this resident */}
                  <div className="grid grid-cols-3 gap-3 pt-4">
                    <SummaryMetric label="Service Requests" value={(mockRequests[selectedResident.id] || mockRequests['default']).length.toString()} icon={ClipboardList} color="blue" />
                    <SummaryMetric label="Unpaid Ledger" value="$150.00" icon={CreditCard} color="orange" />
